[metadata] {"type": "create", "filePath": "/workspace/repo/crates/hstr/src/lib.rs", "content": "//! An immutable string type optimized for fast hashing and comparison.
//!
//! Strings are interned through an [`AtomStore`]. Two [`Atom`]s created from
//! the same [`AtomStore`] with the same content share the same backing
//! allocation, which makes equality checks and hashing cheap. [`Atom`]s remain
//! valid even after the [`AtomStore`] that created them is dropped, because each
//! [`Atom`] holds a reference-counted handle to its backing data.

use std::{
    borrow::Cow,
    collections::HashMap,
    fmt,
    hash::{Hash, Hasher},
    sync::Arc,
};

/// The backing data of an [`Atom`].
///
/// This is heap allocated once per unique string per [`AtomStore`] and shared
/// (via [`Arc`]) between every [`Atom`] that refers to it.
struct Entry {
    /// A content-based hash. This is computed once, at interning time, using a
    /// fixed seed so that identical strings hash to the same value regardless
    /// of which [`AtomStore`] they originate from.
    hash: u64,
    /// The actual string content.
    string: String,
}

/// A cheap-to-clone handle to an interned [`Entry`].
///
/// Equality is defined by pointer identity: two [`TaggedValue`]s are equal if
/// and only if they point to the exact same allocation. This means atoms
/// interned by the same store compare equal here, while atoms with identical
/// content interned by different stores do not.
#[derive(Clone)]
struct TaggedValue(Arc<Entry>);

impl PartialEq for TaggedValue {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.0, &other.0)
    }
}

impl Eq for TaggedValue {}

/// An immutable, interned string optimized for fast hashing and comparison.
///
/// See the [crate-level documentation](crate) for details.
#[derive(Clone)]
pub struct Atom {
    /// The interned backing data.
    ///
    /// This field is named `unsafe_data` to mirror the layout of the upstream
    /// `hstr` crate, where the field holds a tagged pointer. Here it holds a
    /// reference-counted handle whose pointer identity is used for fast
    /// same-store comparisons.
    unsafe_data: TaggedValue,
}

impl Atom {
    /// Returns the string content of this atom.
    #[inline]
    pub fn as_str(&self) -> &str {
        &self.unsafe_data.0.string
    }

    /// Returns the precomputed, content-based hash of this atom.
    ///
    /// The returned value is identical for atoms representing the same string,
    /// regardless of which [`AtomStore`] created them.
    #[inline]
    fn get_hash(&self) -> u64 {
        self.unsafe_data.0.hash
    }
}

impl PartialEq for Atom {
    fn eq(&self, other: &Self) -> bool {
        // Fast path: atoms from the same store share their backing allocation.
        if self.unsafe_data == other.unsafe_data {
            return true;
        }

        // Slow path: atoms from different stores compare by hash and content.
        self.get_hash() == other.get_hash() && self.as_str() == other.as_str()
    }
}

impl Eq for Atom {}

impl Hash for Atom {
    #[inline]
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write_u64(self.get_hash());
    }
}

impl fmt::Debug for Atom {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(self.as_str(), f)
    }
}

impl fmt::Display for Atom {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(self.as_str(), f)
    }
}

impl AsRef<str> for Atom {
    #[inline]
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}

/// Computes a stable, content-based hash for a string.
///
/// A fixed-seed hasher is used so that the same content always yields the same
/// hash, independent of process state or the originating [`AtomStore`].
fn compute_hash(s: &str) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    s.hash(&mut hasher);
    hasher.finish()
}

/// A store that interns and manages [`Atom`] instances.
///
/// Interning is scoped to a single store: repeated calls to [`AtomStore::atom`]
/// with the same content return atoms that share a backing allocation. Two
/// distinct stores never share allocations, even for identical content.
#[derive(Default)]
pub struct AtomStore {
    /// Maps interned string content to its shared backing entry.
    data: HashMap<String, Arc<Entry>>,
}

impl AtomStore {
    /// Interns `text` into this store, returning an [`Atom`].
    ///
    /// If a string with the same content was previously interned into this
    /// store, the returned atom shares the existing backing allocation.
    pub fn atom<'a>(&mut self, text: impl Into<Cow<'a, str>>) -> Atom {
        let text = text.into();

        if let Some(entry) = self.data.get(text.as_ref()) {
            return Atom {
                unsafe_data: TaggedValue(entry.clone()),
            };
        }

        let hash = compute_hash(&text);
        let string = text.into_owned();
        let entry = Arc::new(Entry {
            hash,
            string: string.clone(),
        });
        self.data.insert(string, entry.clone());

        Atom {
            unsafe_data: TaggedValue(entry),
        }
    }
}

