[metadata] {"type": "create", "filePath": "/workspace/repo/crates/hstr/src/tests.rs", "content": "use crate::{Atom, AtomStore};

#[test]
fn same_store_same_content_shares_backing() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("hello");

    // Interning within a single store reuses the backing allocation.
    assert!(a.unsafe_data == b.unsafe_data);
    assert_eq!(a, b);
}

#[test]
fn different_stores_same_content_differ_in_backing_but_are_equal() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    // Distinct stores never share allocations, ...
    assert!(a.unsafe_data != b.unsafe_data);
    // ... but atoms with the same content still compare equal.
    assert_eq!(a, b);
    // ... and hash consistently.
    assert_eq!(a.get_hash(), b.get_hash());
}

#[test]
fn different_content_is_not_equal() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("world");

    assert_ne!(a, b);
}

#[test]
fn atoms_outlive_their_store() {
    let atom = {
        let mut store = AtomStore::default();
        store.atom("persists")
    };

    // The store has been dropped, but the atom is still usable.
    let clone = atom.clone();
    assert_eq!(atom, clone);
    assert_eq!(atom.as_str(), "persists");
}

#[test]
fn accepts_owned_and_borrowed() {
    let mut store = AtomStore::default();

    let from_str = store.atom("shared");
    let from_string = store.atom(String::from("shared"));

    assert_eq!(from_str, from_string);
    assert!(from_str.unsafe_data == from_string.unsafe_data);
}
